const lead = $input.item.json;
const prompt = "Eres comercial senior de una agencia de marketing en Espana. Genera el mensaje de seguimiento perfecto para este lead. Nombre: " + lead.nombre + ". Empresa: " + lead.empresa + ". Cargo: " + lead.cargo + ". Servicio: " + lead.servicio_interesado + ". Dias sin respuesta: " + lead.dias_sin_respuesta + ". Historial: " + lead.historial + ". Temperatura: " + lead.temperatura + ". Intentos previos: " + lead.intentos + ". Genera un mensaje corto maximo 5 lineas adaptado exactamente a su historial y temperatura. Responde SOLO con JSON sin texto adicional ni markdown con estas claves: canal (email o whatsapp), asunto (solo si es email), mensaje (el texto completo listo para enviar), razonamiento (por que este angulo en 1 frase), prioridad (alta media o baja), siguiente_accion (que hacer si no responde en 3 dias).";
const promptLimpio = prompt.replace(/[\u0000-\u001F\u007F]/g, ' ').replace(/\s+/g, ' ').trim();
return { json: { ...lead, prompt: promptLimpio } };

const response = $input.item.json;
let content = '';
if (response.content && Array.isArray(response.content)) {
  content = response.content[0].text || '';
} else if (response.text) {
  content = response.text;
} else {
  content = JSON.stringify(response);
}
let mensaje;
try {
  content = content.replace(/```json/gi, '').replace(/```/g, '').trim();
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    mensaje = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error('No JSON encontrado');
  }
} catch(e) {
  mensaje = {
    canal: 'email',
    asunto: 'Seguimiento',
    mensaje: 'Error al generar mensaje. Vuelve a ejecutar.',
    razonamiento: 'Error de parseo',
    prioridad: 'media',
    siguiente_accion: 'Reintentar'
  };
}
const leadData = $input.item.json;
return {
  json: {
    nombre: leadData.nombre || '',
    empresa: leadData.empresa || '',
    cargo: leadData.cargo || '',
    temperatura: leadData.temperatura || '',
    dias_sin_respuesta: leadData.dias_sin_respuesta || 0,
    intentos: leadData.intentos || 0,
    historial: leadData.historial || '',
    servicio_interesado: leadData.servicio_interesado || '',
    presupuesto: leadData.presupuesto || '',
    mensaje_generado: mensaje
  }
};
